    safety = true;
    evOverCurrentUntil = now + EV_OVERCURRENT_COOLDOWN_MS;
    flow.set("EV_overcurrent_cooldown_until", evOverCurrentUntil);
    reason.push("EV stopped >38A, cooldown 5 min");
}
else if (now < evOverCurrentUntil) {
    evKwReq = 0;
    safety = true;
    reason.push("EV cooldown active");
}
else if (maxI > 35) {
    evKwReq = Math.max(0, evKwReq - 1);
    safety = true;
    reason.push("EV reduced >35A");
}
else {
    flow.set("EV_overcurrent_cooldown_until", 0);
}
if (evKwReq > 0 && evKwReq < EV_MIN_KW) evKwReq = 0;

// -------------------------
// Battery decision
// -------------------------
// -------------------------
// Battery decision
// -------------------------
let battMode = s.battery_mode;
let battW = 0;
let battControl = 'AUTO';

if (battMode === 'CHARGE') {
    battControl = 'CHARGE';
    battW = -5000;
}
else if (battMode === 'HOLD') {
    battControl = 'HOLD';
    battW = 0;
}
else {

    // Negative afname has priority over forecast and over "EV active = hold".
    if (s.ems_mode === 'SUMMER' && priceValid && buy < 0) {
        if (connected && s.ev_enabled && evKwReq > 0) {
            const BATTERY_L1_CURRENT_LIMIT_A = 34;
            const BATTERY_MIN_CHARGE_W = 500;
            const BATTERY_MAX_CHARGE_W_LOCAL = batteryChargeLimitBySoc(SOC);

            let evCurrentA = clamp(
                (evKwReq * 1000) / (Math.sqrt(3) * 400),
                0,
                16
            );

           let batteryChargeCurrentA = Math.max(0, -P_Batt_ctrl / 230);

// I1 already includes the actual EV current.
// So remove the actual EV current first, then reserve room for the EV target.
let actualEvCurrentA = Actual_P_EV > 100
    ? clamp(Actual_P_EV / (Math.sqrt(3) * 400), 0, 16)
    : 0;

let currentWithoutBatteryAndEvA =
    I1 - batteryChargeCurrentA - actualEvCurrentA;

let remainingBatteryCurrentA =
    BATTERY_L1_CURRENT_LIMIT_A -
    currentWithoutBatteryAndEvA -
    evCurrentA;
            let allowedBatteryChargeW =
                Math.floor(remainingBatteryCurrentA * 230 / 100) * 100;

            allowedBatteryChargeW = clamp(
                allowedBatteryChargeW,
                0,
                BATTERY_MAX_CHARGE_W_LOCAL
            );

            if (allowedBatteryChargeW >= BATTERY_MIN_CHARGE_W) {
                battControl = 'CHARGE';
                battW = -allowedBatteryChargeW;
                reason.push(`Negative afname: EV max, battery charging ${allowedBatteryChargeW}W with remaining L1 headroom`);
            } else {
                battControl = 'HOLD';
                battW = 0;
                reason.push('Negative afname: EV max, no L1 headroom for battery');
            }
        } else {
            battControl = 'CHARGE';
            battW = -batteryChargeLimitBySoc(SOC);
            reason.push('Negative afname: battery charging');
        }
    }
    else if (forecastActive) {
        if (forecastPlan.chargeNow && SOC < 99.5) {
            battControl = 'CHARGE';
            battW = -clamp(forecastPlan.chargePowerW, FORECAST_MIN_CHARGE_W, BATTERY_MAX_CHARGE_W);
            reason.push(forecastPlan.note);
        } else {
            battControl = 'HOLD';
            battW = 0;
            reason.push(forecastPlan.note);
        }
    }
    else if (Actual_P_EV > 100 || evKwReq > 0) {
        battControl = 'HOLD';
        battW = 0;
        reason.push('EV active: battery held');
    }
    else {
        battControl = 'AUTO';
        battW = 0;
    }
}

