function ensureSingleProfile(profile) {
    if (!profile || typeof profile !== "object") profile = {};

    if (!profile.home_weekday || !Array.isArray(profile.home_weekday) || profile.home_weekday.length < 96) {
        profile.home_weekday = makeArr(null);
    }
    if (!profile.home_weekend || !Array.isArray(profile.home_weekend) || profile.home_weekend.length < 96) {
        profile.home_weekend = makeArr(null);
    }
    if (!profile.pv_factor || !Array.isArray(profile.pv_factor) || profile.pv_factor.length < 96) {
        profile.pv_factor = makeArr(1.0);
    }

    if (!profile.counts || typeof profile.counts !== "object") profile.counts = {};
    if (!profile.counts.home_weekday || !Array.isArray(profile.counts.home_weekday) || profile.counts.home_weekday.length < 96) {
        profile.counts.home_weekday = makeArr(0);
    }
    if (!profile.counts.home_weekend || !Array.isArray(profile.counts.home_weekend) || profile.counts.home_weekend.length < 96) {
        profile.counts.home_weekend = makeArr(0);
    }
    if (!profile.counts.pv_factor || !Array.isArray(profile.counts.pv_factor) || profile.counts.pv_factor.length < 96) {
        profile.counts.pv_factor = makeArr(0);
    }

    if (!profile.last_update) profile.last_update = 0;
    if (!profile.last_update_text) profile.last_update_text = "";

    return profile;
}

function ensureBucketedProfile(rawProfile) {
    if (!rawProfile || typeof rawProfile !== "object") {
        return {
            normal: emptyProfile(),
            holiday: emptyProfile()
        };
    }

    let looksLikeOldSingleProfile =
        Array.isArray(rawProfile.home_weekday) ||
        Array.isArray(rawProfile.home_weekend) ||
        Array.isArray(rawProfile.pv_factor);

    if (looksLikeOldSingleProfile) {
        return {
            normal: ensureSingleProfile(rawProfile),
            holiday: emptyProfile()
        };
    }

    return {
        normal: ensureSingleProfile(rawProfile.normal),
        holiday: ensureSingleProfile(rawProfile.holiday)
    };
}

function ema(oldVal, newVal, count, alphaFast, alphaSlow) {
    if (oldVal === null || oldVal === undefined || !isFinite(Number(oldVal))) return newVal;
    let alpha = count < 8 ? alphaFast : alphaSlow;
    return oldVal * (1 - alpha) + newVal * alpha;
}

