let warning = {
    payload: "",
    color: "green"
};

let restart = null;

if (!stalePower && !staleSoc) {
    flow.set("battery_modbus_warning", false);
    warning.payload =
        "Battery data OK | Power " + ageText(effectivePowerAge) +
        " | SoC " + ageText(effectiveSocAge) +
        (httpOk ? " | HTTP fallback OK" : "");
    warning.color = "green";
    return [warning, null];
}

flow.set("battery_modbus_warning", true);

warning.payload =
    "WARNING: Battery data stale | Power " +
    ageText(effectivePowerAge) +
    " | SoC " +
    ageText(effectiveSocAge) +
    " | Modbus power " +
    ageText(modbusPowerAge) +
    " | Modbus SoC " +
    ageText(modbusSocAge) +
    " | HTTP " +
    ageText(httpAge);

warning.color = "red";

// Only soft/hard reset when MODBUS POWER is stale.
// Do not restart Node-RED just because Modbus SoC is stale if HTTP SoC is OK.
let stale10 = modbusPowerAge > 10 * 60 * 1000;
let stale20 = modbusPowerAge > 20 * 60 * 1000;

if (stale10 && now - lastSoftReset > 10 * 60 * 1000) {
    flow.set("battery_modbus_pause_until", now + 10000);
    flow.set("battery_modbus_soft_reset_ts", now);
    node.warn("Battery Modbus power stale >10 min: pausing battery polling for 10 seconds");
}

if (stale20 && now - lastHardReset > 30 * 60 * 1000) {
    flow.set("battery_modbus_hard_reset_ts", now);
    node.warn("Battery Modbus power stale >20 min: restarting Node-RED");

    restart = {
        payload: "sudo systemctl restart nodered"
    };
}

return [warning, restart];

function n(v,d=0){ v=Number(v); return isFinite(v)?v:d; }
function yes(v){ return v ? 'YES' : 'NO'; }
function fmtKw(v){ return n(v,0).toFixed(1) + ' kW'; }
function fmtW(v){ return Math.round(n(v,0)) + ' W'; }
function fmtPrice(v){ return isFinite(Number(v)) ? Number(v).toFixed(2) + ' c/kWh' : '--'; }
function fmtTime(ts){
    ts = Number(ts);
    if (!isFinite(ts) || ts <= 0) return '--';
    let d = new Date(ts);
    return d.toLocaleTimeString('nl-BE', {hour:'2-digit', minute:'2-digit', second:'2-digit'});
}
function ageText(ts){
    ts = Number(ts);
    if (!isFinite(ts) || ts <= 0) return '--';
    let sec = Math.max(0, Math.round((Date.now() - ts)/1000));
    return sec + 's ago';
}

let d = flow.get('ems_decision_dashboard') || {};
let s = flow.get('ems_settings') || {};

msg.payload = {
    context: {
        mode: d.mode || s.ems_mode || '--',
        priceValid: d.priceValid === true,
        buy: fmtPrice(d.buy),
        sell: fmtPrice(d.sell),
        quarter: d.quarter ?? '--',
        evConnected: yes(d.evConnected),
        evEnabled: yes(d.evEnabled),
        evSolar: yes(d.evSolar),
        evManual: yes(d.evManual) + ' / ' + fmtKw(d.evManualKw),
        evTimer: yes(d.evTimer) + ' / ' + fmtKw(d.evTimerKw),
        schedulerActive: yes(d.schedulerActive),
        batteryMode: d.batteryMode || '--',
        soc: Math.round(n(d.soc,0)) + '%',
        solarMode: d.solarMode || '--',
        forecastBased: yes(d.forecastBased),
        forecastEv: yes(d.forecastEvEnabled) + ' / ' + n(d.forecastEvKwh,10) + ' kWh'
    },
    decisions: {
        ev: {
            target: fmtKw(d.evTargetKw),
            amps: n(d.evTargetA,0).toFixed(1) + ' A',
            actual: fmtKw(n(d.evActualW,0)/1000),
            reason: d.evReason || '--',
            status: d.evTargetKw > 0 ? 'ACTIVE' : 'IDLE'
        },
        battery: {
            target: fmtW(d.batteryTargetW),
            mode: d.batteryControl || '--',
            reason: d.batteryReason || '--',
            status: n(d.batteryTargetW,0) < -50 ? 'CHARGE' : (n(d.batteryTargetW,0) > 50 ? 'DISCHARGE' : 'HOLD/AUTO')
        },
        solar: {
            target: fmtKw(d.solarTargetKw),
            actual: fmtW(d.pvActualW),
            reason: d.solarReason || '--',
            status: n(d.solarTargetKw,10) < 0.1 ? 'STOPPED' : 'OPEN/LIMITED'
        }
    },
    timing: {
        lastDecision: fmtTime(d.lastDecisionTs),
        lastDecisionAge: ageText(d.lastDecisionTs),
        nextDecision: fmtTime(d.nextDecisionTs),
        probeStatus: d.probeStatus || '--',
        nextProbe: d.nextProbeText || '--',
        importGrace: d.importGraceText || '--'
    },
    trace: Array.isArray(d.trace) ? d.trace : [],
    safety: d.safety === true
};

return msg;

// EDIT THESE TWO VALUES
const SMA_SBS_IP = "YOUR_SMA_BATTERY_IP";
const SMA_PASSWORD = "YOUR_SMA_PASSWORD_HERE";

let sid = flow.get("sma_sbs_http_sid");
let sidTs = Number(flow.get("sma_sbs_http_sid_ts")) || 0;
let sidAge = Date.now() - sidTs;

// Reuse SID for 10 minutes
if (sid && sidAge < 10 * 60 * 1000) {
    msg.sma_sbs_ip = SMA_SBS_IP;
    msg.sid = sid;
    msg.skipLogin = true;
    return [null, msg];
}

msg.sma_sbs_ip = SMA_SBS_IP;
msg.url = `https://${SMA_SBS_IP}/dyn/login.json`;
msg.method = "POST";
msg.headers = { "Content-Type": "application/json" };
msg.payload = { right: "usr", pass: SMA_PASSWORD };

return [msg, null];

let sid = msg.payload?.result?.sid;

if (!sid) {
    node.warn("SMA SBS HTTP login failed: " + JSON.stringify(msg.payload));
    flow.set("diag_battery_http_status", "login_err");
    return null;
}



msg.sid = sid;
flow.set("sma_sbs_http_sid_last_ok", Date.now());
flow.set("sma_sbs_http_sid", sid);
flow.set("sma_sbs_http_sid_ts", Date.now());
return msg;

msg.url = `https://${msg.sma_sbs_ip}/dyn/getValues.json?sid=${msg.sid}`;
msg.method = "POST";
msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    destDev: [],
    keys: [
        "6100_00696E00",
        "6100_00496900",
        "6100_00496A00",
        "6100_00295A00"
    ]
};
return msg;

function n(v, d = null) {
    v = Number(v);
    return isFinite(v) ? v : d;
}

// Keep false for the first days: use HTTP mainly as SoC fallback.
// Change to true only if you want HTTP to overwrite P_Batt as primary battery power.
const USE_HTTP_POWER_AS_PRIMARY = true;

let result = msg.payload?.result;
if (!result || typeof result !== "object") {
    node.warn("SMA SBS HTTP: no result object: " + JSON.stringify(msg.payload));
    flow.set("diag_battery_http_status", "err_no_result");
    return null;
}

let deviceKey = Object.keys(result).find(k =>
    result[k] && (
        result[k]["6100_00696E00"] ||
        result[k]["6100_00496900"] ||
        result[k]["6100_00496A00"] ||
        result[k]["6100_00295A00"]
    )
);

if (!deviceKey) {
    node.warn("SMA SBS HTTP: battery device not found");
    flow.set("diag_battery_http_status", "err_no_battery_device");
    return null;
}

let dev = result[deviceKey];

function readVal(key) {
    let obj = dev[key];
    if (!obj) return null;

    if (obj["7"] && obj["7"][0] && obj["7"][0].val !== undefined) {
        return n(obj["7"][0].val);
    }

    let firstChannel = Object.keys(obj)[0];
    if (
        firstChannel &&
        obj[firstChannel] &&
        obj[firstChannel][0] &&
        obj[firstChannel][0].val !== undefined
    ) {
        return n(obj[firstChannel][0].val);
    }

    return null;
}

let battCapacityWh = readVal("6100_00696E00");
let battChargingW = readVal("6100_00496900");
let battDischargingW = readVal("6100_00496A00");
let battSoc = readVal("6100_00295A00");

if (battChargingW === null) battChargingW = 0;
if (battDischargingW === null) battDischargingW = 0;

let P_net_batt_charge = 0;

if (battChargingW > 20) {
    P_net_batt_charge = -battChargingW;
}
else if (battDischargingW > 20) {
    P_net_batt_charge = battDischargingW;
}

let now = Date.now();

if (battSoc !== null && battSoc >= 0 && battSoc <= 100) {
    let soc = Math.round(battSoc);
    flow.set("Battery_Soc", soc);
    flow.set("ems_battery_soc", soc);
    flow.set("Battery_Soc_last_good", soc);
    flow.set("battery_soc_last_seen", now);
    flow.set("diag_battery_soc_read_ts", now);
    flow.set("diag_battery_soc_read_status", "ok_http");
} else {
    node.warn("SMA SBS HTTP: invalid SoC: " + battSoc);
}

let U1 = n(flow.get("U1"), 230);
if (U1 < 180 || U1 > 260) U1 = 230;

let I_net_batt_charge = Math.round((P_net_batt_charge / U1) * 10) / 10;

if (USE_HTTP_POWER_AS_PRIMARY) {
    flow.set("P_Batt", P_net_batt_charge);
    flow.set("P1_Batt", P_net_batt_charge);
    flow.set("P2_Batt", 0);
    flow.set("P3_Batt", 0);
    flow.set("I1_Batt", I_net_batt_charge);
    flow.set("I2_Batt", 0);
    flow.set("I3_Batt", 0);
    flow.set("diag_battery_power_read_ts", now);
}

flow.set("sma_battery_http_last_good", now);
flow.set("diag_battery_http_status", "ok");
flow.set("diag_battery_http_device_key", deviceKey);
flow.set("diag_battery_http_soc", battSoc);
flow.set("diag_battery_http_power", P_net_batt_charge);

msg.topic = "Storage";
msg.payload = {
    P_net_batt_charge,
    P_batt_capacity: battCapacityWh,
    P_batt_charge: battSoc,
    I_net_batt_charge,
    P1_net_batt_charge: P_net_batt_charge,
    P2_net_batt_charge: 0,
    P3_net_batt_charge: 0,
    source: "SMA_HTTP",
    useHttpPowerAsPrimary: USE_HTTP_POWER_AS_PRIMARY
};

return msg;

if (!msg.payload || !msg.payload.result || !msg.payload.result.sid) {
    node.warn("SMA login failed/no SID: " + JSON.stringify(msg.payload));
    flow.set("diag_battery_http_status", "login_err");
    return null;
}

msg.sid = msg.payload.result.sid;
flow.set("diag_battery_http_status", "login_ok");
return msg;

//var arr_p_supply_to_grid_info_PV = msg.payload.result["0198-xxxxx2AE"]["6100_40263F00"];// Does NOT exist
var arr_p_batt_capacity = msg.payload.result["0169-xxxxxBEA"]["6100_00696E00"];
var arr_p_batt_charging = msg.payload.result["0169-xxxxxBEA"]["6100_00496900"];
var arr_p_batt_discharging = msg.payload.result["0169-xxxxxBEA"]["6100_00496A00"];
var arr_p_batt_charge = msg.payload.result["0169-xxxxxBEA"]["6100_00295A00"];
var P_net_batt_charge = null;

//P_supply_to_grid_info_PV = arr_p_supply_to_grid_info_PV["1"][0].val;
var P_batt_charging = arr_p_batt_charging["7"][0].val;
var P_batt_discharging = arr_p_batt_discharging["7"][0].val;
var P_batt_capacity = arr_p_batt_capacity["7"][0].val;
var P_batt_charge = arr_p_batt_charge["7"][0].val;

if (P_batt_charging > 0){
    P_net_batt_charge = -P_batt_charging;
}
if (P_batt_discharging > 0){
    P_net_batt_charge = P_batt_discharging;
}

var P1_net_batt_charge = P_net_batt_charge; // connected to L1
var P2_net_batt_charge =0;
var P3_net_batt_charge =0;

var I_net_batt_charge=Math.round(P_net_batt_charge/flow.get("U1"));

msg.payload = {P_net_batt_charge,P_batt_capacity,P_batt_charge,I_net_batt_charge,P1_net_batt_charge,P2_net_batt_charge,P3_net_batt_charge}
msg.topic = "Storage";

flow.set("Battery_Soc", P_batt_charge);

return msg;
